insert into ponew values
(1, 1, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Cells of which layer of the epidermis are keratinised and dead?', '["Stratum granulosum", "Stratum spinosum", "Stratum corneum", "Stratum basale"]'::jsonb, 2, 'The stratum corneum, the outermost layer, is made of dead keratinised cells.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 2, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The diaphragm is supplied by the phrenic nerve, which arises from the spinal roots:', '["C3, C4 and C5", "C6, C7 and C8", "C1 and C2", "T1 to T6"]'::jsonb, 0, '''C3, 4, 5 keeps the diaphragm alive.'' High cervical cord injury or phrenic nerve injury (e.g. during neck or thoracic surgery) can cause diaphragmatic paralysis.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 3, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The portion of the cervix that protrudes into the vagina is covered by:', '["Columnar epithelium", "Squamous epithelium", "Transitional epithelium", "Cuboidal epithelium"]'::jsonb, 1, 'The ectocervix, the part protruding into the vagina, is covered by stratified squamous epithelium. The endocervical canal is lined by columnar epithelium.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 4, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Heparin and histamine are secreted by:', '["Basophils", "Neutrophils", "Plasma cells", "B lymphocytes"]'::jsonb, 0, 'Basophils, like mast cells, secrete heparin and histamine.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 5, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which gastrointestinal process refers to the physical and chemical breakdown of food into absorbable units?', '["Excretion", "Absorption", "Transportation", "Digestion"]'::jsonb, 3, 'Digestion is the breakdown of food (mechanically and chemically) into smaller, absorbable molecules.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 6, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which spinal nerves give rise to the cervical plexus?', '["C3–T3", "C1–C4", "T1–T12", "C5–T1"]'::jsonb, 1, 'The cervical plexus is formed by the anterior rami of C1–C4. C5–T1 form the brachial plexus.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 7, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The layer of the heart responsible for its pumping contraction is the:', '["Epicardium", "Pericardium", "Myocardium", "Endocardium"]'::jsonb, 2, 'The myocardium is the thick muscular middle layer responsible for the heart''s contractile pumping action.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 8, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Serum is blood plasma minus its:', '["Fibrinogen", "Albumin", "Calcium ions", "Sodium ions"]'::jsonb, 0, 'Serum is plasma with the clotting proteins, chiefly fibrinogen, removed.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 9, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Body temperature is regulated mainly by the:', '["Hypothalamus", "Cerebellum", "Thyroid gland", "Medulla oblongata"]'::jsonb, 0, 'The hypothalamus compares core temperature with its set point and triggers heat loss or heat gain. General anaesthesia impairs this control, so patients become hypothermic in theatre.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 10, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The 6th cranial nerve is the:', '["Trigeminal nerve", "Oculomotor nerve", "Abducent nerve", "Facial nerve"]'::jsonb, 2, 'Cranial nerve VI, the abducent (abducens) nerve, supplies the lateral rectus, which abducts the eye.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 11, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Absorption of digested nutrients occurs primarily in the:', '["Stomach", "Small intestine", "Oesophagus", "Large intestine"]'::jsonb, 1, 'The small intestine, with its large surface area from villi and microvilli, is the primary site of nutrient absorption.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 12, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Vigorous exercise could release high amounts of _____________ into the urine', '["Ascorbic acid", "Uric acid", "Albumin", "Glucose"]'::jsonb, 2, 'The correct answer is: Albumin.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 13, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'If stroke volume is 70 mL and heart rate is 75 beats/min, the cardiac output is:', '["0.525 L/min", "1.07 L/min", "5.25 L/min", "52.5 L/min"]'::jsonb, 2, 'Cardiac output = stroke volume × heart rate = 70 mL × 75 = 5,250 mL/min = 5.25 L/min (normal 4–8 L/min).', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 14, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'A patient with blood group O negative is often called the:', '["Universal recipient", "Rh-positive donor", "Least compatible donor", "Universal donor"]'::jsonb, 3, 'O negative red cells lack A, B, and Rh(D) antigens, making them compatible (in emergencies) with recipients of any ABO/Rh type — hence ''universal donor''.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 15, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Most nutrient absorption occurs in the:', '["Stomach", "Large intestine", "Oesophagus", "Small intestine"]'::jsonb, 3, 'The small intestine, with its vast surface area from villi and microvilli, is the primary site of digestion and nutrient absorption.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 16, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The olfactory nerve is responsible for:', '["Smell", "Hearing", "Vision", "Taste"]'::jsonb, 0, 'The olfactory nerve (CN I) carries the sense of smell.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 17, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Blood flows from the right atrium to the right ventricle through which valve?', '["Bicuspid (mitral)", "Tricuspid", "Pulmonary", "Aortic"]'::jsonb, 1, 'The right atrioventricular valve is the tricuspid valve. The left is the mitral (bicuspid).', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 18, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'How many pulmonary veins empty into the right atrium?', '["Two", "One", "None", "Four"]'::jsonb, 2, 'The four pulmonary veins drain oxygenated blood into the LEFT atrium. None enter the right atrium.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 19, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which endocrine gland is most directly involved in immune function?', '["Adrenal glands", "Thymus", "Adenohypophysis", "Pancreas"]'::jsonb, 1, 'The thymus is where T lymphocytes mature (thymosin). It is the endocrine gland most involved in immunity.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 20, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The normal adult glomerular filtration rate is approximately:', '["1,200 mL/min", "125 mL/min", "500 mL/min", "25 mL/min"]'::jsonb, 1, 'Normal GFR is about 120–125 mL/min (180 L/day), of which about 99% is reabsorbed. Renal blood flow is about 1,200 mL/min.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 21, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The correct order of the stages of fracture (bone) healing is:', '["Granulation, remodelling, haematoma, consolidation, callus", "Callus, haematoma, granulation, remodelling, consolidation", "Remodelling, haematoma, granulation, callus, consolidation", "Haematoma, granulation, callus, consolidation, remodelling"]'::jsonb, 3, 'Bleeding forms a haematoma, which is replaced by granulation tissue, then soft and hard callus. Woven bone consolidates into lamellar bone and is remodelled over months.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 22, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which among the following is the correct sequence in which urine flows through the kidney toward the urinary bladder?', '["Papillary duct, minor calyx, major calyx, renal pelvis, ureter", "Minor calyx, major calyx, papillary duct, renal pelvis, ureter", "Papillary duct, major calyx, minor calyx, ureter, renal pelvis", "Renal pelvis, major calyx, minor calyx, papillary duct, ureter"]'::jsonb, 0, 'The correct answer is: Papillary duct, minor calyx, major calyx, renal pelvis, ureter.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 23, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Stimulation of the sympathetic nervous system typically causes which cardiac effect?', '["Increased heart rate and contractility", "Decreased heart rate and contractility", "No cardiac effect", "Complete heart block"]'::jsonb, 0, 'Sympathetic stimulation releases catecholamines that increase heart rate (chronotropy) and contractility (inotropy) via beta-1 receptors.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 24, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Most of the body cells'' energy is derived from chemical reactions, which can only take place in the presence of:', '["Oxygen", "Carbon dioxide", "Blood", "ATP"]'::jsonb, 0, 'Aerobic metabolism (oxidative phosphorylation) needs oxygen and produces most of the cell''s ATP.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 25, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Vital cardiorespiratory centres are located in the:', '["Occipital lobe", "Hypothalamus only", "Medulla oblongata", "Cerebellum"]'::jsonb, 2, 'The medulla oblongata houses the cardiac and respiratory centres that regulate heart rate, blood pressure, and breathing rhythm.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 26, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The bony labyrinth is found in the:', '["Auricle", "External auditory canal", "Middle ear", "Inner ear"]'::jsonb, 3, 'The bony labyrinth (cochlea, vestibule, semicircular canals) lies in the inner ear within the temporal bone.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 27, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The gag reflex primarily depends on which cranial nerve(s)?', '["Cranial nerve VII only", "Cranial nerves I and II", "Cranial nerves IX and X", "Cranial nerve XII only"]'::jsonb, 2, 'The glossopharyngeal (IX) and vagus (X) nerves mediate the sensory and motor components of the gag reflex, relevant to airway protection assessment.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 28, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which of the following statements concerning the ureters is false?', '["They are composed of three tunics", "They are located within the peritoneal cavity", "The mucosa of each ureter is composed of transitional epithelium", "Muscular peristaltic waves move urine through the ureters"]'::jsonb, 1, 'The correct answer is: They are located within the peritoneal cavity.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 29, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Neurones are also known as:', '["Ganglia", "Glial cells", "Axons", "Nerve cells"]'::jsonb, 3, 'Neurones are nerve cells, the functional units of the nervous system.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 30, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The brain uses about what percentage of the body''s oxygen consumption?', '["10%", "20%", "15%", "5%"]'::jsonb, 1, 'The brain is about 2% of body weight but uses about 20% of the body''s oxygen.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 31, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which of the following statements concerning the kidneys is false?', '["They are positioned between the third and fifth lumbar", "They are retroperitoneal", "They each contain 8 to 15 renal pyramids", "They each have a distinct renal cortex and renal medulla region"]'::jsonb, 0, 'The correct answer is: They are positioned between the third and fifth lumbar.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 32, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The pancreas functions as both an endocrine and exocrine organ; insulin is an example of its:', '["Neither function", "Endocrine function", "Only a digestive enzyme", "Exocrine function"]'::jsonb, 1, 'Insulin, secreted by the islets of Langerhans directly into the bloodstream, exemplifies the pancreas''s endocrine function, distinct from its exocrine secretion of digestive enzymes into the duodenum.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 33, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The part of the CNS housed within the cranial vault is the:', '["Medulla oblongata only", "Brain", "Brainstem only", "Spinal cord"]'::jsonb, 1, 'The brain lies within the cranial vault. The spinal cord lies in the vertebral canal.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 34, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Filtration of blood in the nephron primarily occurs at the:', '["Glomerulus", "Collecting duct", "Loop of Henle", "Distal convoluted tubule"]'::jsonb, 0, 'The glomerulus, a capillary tuft within Bowman''s capsule, is the site of filtration of plasma into the nephron.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 35, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which of the following are fewest in number but largest in diameter?', '["Terminal bronchioles", "Alveoli", "Tertiary bronchi", "Alveolar ducts"]'::jsonb, 2, 'Tertiary (segmental) bronchi are the widest and fewest of these. The airways get narrower and more numerous towards the alveoli.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 36, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which of the following is NOT routinely tested as a transfusion-transmissible infection in the blood bank?', '["Hepatitis A", "Hepatitis B", "Malaria", "HIV"]'::jsonb, 0, 'Donor blood is screened for HIV, hepatitis B, hepatitis C and syphilis (and malaria in endemic areas). Hepatitis A is not routinely tested.', 'NNP 412 · Applied Biochemistry'),
(1, 37, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', '20, PCO2 55 mm hg, PO2 65 mm hg, HCO3 22 m mol. What does this mean?', '["Respiratory acidosis", "Metabolic acidosis", "Metabolic alkalosis", "Respiratory alkalosis"]'::jsonb, 0, 'Acidic pH with elevated PCO2 and roughly normal HCO3 indicates respiratory acidosis.', 'NNP 412 · Applied Biochemistry'),
(1, 38, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'FFP is thawed and must be infused within:', '["6 hours", "4 hours", "30 minutes", "24 hours"]'::jsonb, 3, 'Thawed FFP is stable for 24 hours at 1-6°C.', 'NNP 412 · Applied Biochemistry'),
(1, 39, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A 65 year old female is put on Ventilator due to acute respiratory Failure (ARF).The ABG''s result tell the following findings, PH=7.5,PCO2=50,HCO3=30,PO2=85.What would be the more likely diagnosis:', '["Complete compensation", "Both a & b", "Partial compensation", "No compensation"]'::jsonb, 2, 'pH still abnormal (7.5) despite compensatory changes in PCO2/HCO3 means only partial compensation has occurred.', 'NNP 412 · Applied Biochemistry'),
(1, 40, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A nurse is interpreting an ABG for a patient. The results are pH 7.28, PaCO₂ 60 mmHg, and HCO₃⁻ 24 mEq/L. This indicates:', '["Compensated metabolic acidosis", "Partially compensated respiratory alkalosis", "Uncompensated respiratory alkalosis", "Uncompensated respiratory acidosis"]'::jsonb, 3, 'The low pH (< 7.35) indicates acidosis. The high PaCO₂ (> 45 mmHg) indicates a respiratory cause. The normal bicarbonate (HCO_{3}^{-}) level indicates that the kidneys have not had time to compensate. Therefore, the patient has uncompensated respiratory acidosis.', 'NNP 412 · Applied Biochemistry'),
(1, 41, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient''s blood culture grows a common skin organism (coagulase-negative Staphylococcus) from only one of two culture sets drawn. The nurse understands this pattern often suggests:', '["Definite true bacteraemia requiring immediate aggressive treatment with no further consideration", "Possible contamination, requiring clinical correlation rather than automatic treatment", "A laboratory error with no clinical relevance", "Always indicates central line infection"]'::jsonb, 1, 'A single positive culture for a common skin contaminant (like coagulase-negative Staph) out of multiple sets often suggests contamination rather than true infection, requiring clinical correlation before treatment decisions.', 'NNP 412 · Applied Biochemistry'),
(1, 42, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A blood film showing fragmented red cells (schistocytes) suggests:', '["Vitamin B12 deficiency with large cells", "A normal blood film in a healthy adult", "Microangiopathic haemolysis (DIC, TTP)", "Iron deficiency from chronic bleeding"]'::jsonb, 2, 'TTP needs urgent plasma exchange.', 'NNP 412 · Applied Biochemistry'),
(1, 43, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient with severe sepsis is suspected of having DIC. Which finding helps confirm this?', '["Petechiae", "Clear breath sounds", "Bradycardia", "Polyuria"]'::jsonb, 0, 'Petechiae, purpura and oozing show the consumption coagulopathy of DIC.', 'NNP 412 · Applied Biochemistry'),
(1, 44, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient with hypochloremia (Cl⁻ 88 mEq/L) and metabolic alkalosis should receive:', '["0.45% saline IV", "Acetazolamide", "Ammonium chloride", "Potassium supplements"]'::jsonb, 0, 'Hypochloremic metabolic alkalosis (e.g., from vomiting) responds to chloride-rich fluids (e.g., 0.9% or 0.45% saline).', 'NNP 412 · Applied Biochemistry'),
(1, 45, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which blood cells are destroyed in a delayed haemolytic transfusion reaction?', '["White blood cells", "Red blood cells", "Plasma cells", "Platelets"]'::jsonb, 1, 'A delayed haemolytic transfusion reaction is immune destruction of the transfused red cells (RBCs) days after transfusion, usually from an anamnestic antibody response.', 'NNP 412 · Applied Biochemistry'),
(1, 46, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A fall in HCO3 causing acidosis indicates the disorder is:', '["Always fatal", "Metabolic", "Purely a lab error", "Respiratory"]'::jsonb, 1, 'Bicarbonate is controlled by the kidneys, so a HCO3-driven pH problem is classified as metabolic.', 'NNP 412 · Applied Biochemistry'),
(1, 47, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A 55 year old male came to the ER with the complaint of severe Shortness of Breath. The physician advised for ABG''s. The result was pH=7.20, PCO2=50, HCO3=24, PO2=80.A BSN student is looking at the values and makes the conclusion as:', '["Respiratory Alkalosis", "Metabolic Acidosis", "Metabolic Alkalosis", "Respiratory Acidosis"]'::jsonb, 3, 'Low pH with a high PCO2 and normal HCO3 is a respiratory acidosis.', 'NNP 412 · Applied Biochemistry'),
(1, 48, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'To prevent graft-versus-host disease, blood is:', '["Washed", "Frozen", "Leukocyte-reduced", "Irradiated"]'::jsonb, 3, 'Irradiation inactivates donor lymphocytes.', 'NNP 412 · Applied Biochemistry'),
(1, 49, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'In metabolic acidosis, the expected respiratory compensation (fall in PaCO2) is calculated as:', '["No compensation ever occurs", "2 × the pH change", "1.25 × the HCO3 fall", "0.1 × the HCO3 fall"]'::jsonb, 2, 'The lungs blow off CO2 to help correct the acidosis, and this expected compensation follows this specific formula.', 'NNP 412 · Applied Biochemistry'),
(1, 50, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A bone marrow condition in which all formed elements of the blood are simultaneously reduced is:', '["Thalassaemia", "Haemolytic anaemia", "Iron-deficiency anaemia", "Aplastic anaemia"]'::jsonb, 3, 'Aplastic anaemia is bone marrow failure with pancytopenia, a reduction in all three cell lines at once.', 'NNP 412 · Applied Biochemistry'),
(1, 51, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A sickle cell crisis transfusion target is usually HbS below:', '["90%", "70%", "30%", "50%"]'::jsonb, 2, 'Exchange transfusion lowers HbS rapidly in severe crises.', 'NNP 412 · Applied Biochemistry'),
(1, 52, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Platelets are administered through:', '["No filter", "A microaggregate filter", "A specialized platelet filter", "A standard blood filter"]'::jsonb, 3, 'Platelets use standard filters; microaggregate filters remove platelets.', 'NNP 412 · Applied Biochemistry'),
(1, 53, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Glycosylated haemoglobin (HbA1c) reflects average blood glucose control over approximately:', '["A single fasting measurement", "The past 5 years", "The past 24 hours", "The past 2–3 months"]'::jsonb, 3, 'HbA1c reflects the percentage of haemoglobin glycosylated over the roughly 120-day lifespan of red blood cells, giving an average picture of glycaemic control over about 2–3 months.', 'NNP 412 · Applied Biochemistry'),
(1, 54, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'For a patient with multiple febrile reactions, the nurse requests:', '["Volume-reduced platelets", "Irradiated blood", "Washed RBCs", "Leukocyte-reduced blood"]'::jsonb, 3, 'Leukocyte reduction prevents febrile non-hemolytic reactions.', 'NNP 412 · Applied Biochemistry'),
(1, 55, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'ESR and CRP are best described as:', '["Measures of clotting function", "Highly specific for a single disease", "Direct measures of infection type", "Nonspecific markers of inflammation"]'::jsonb, 3, 'Erythrocyte sedimentation rate and C-reactive protein rise with inflammation from many causes and are nonspecific — useful for trend monitoring rather than diagnosing a specific condition.', 'NNP 412 · Applied Biochemistry'),
(1, 56, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'An elementary student, was rushed to the hospital due to vomiting and a decreased level of consciousness. The patient displays slow and deep (Kussmaul breathing), and he is lethargic and irritable in response to stimulation. He appears to be dehydrated—his eyes are sunken and mucous membranes are dry—and he has a two-week history of polydipsia, polyuria, and weight loss. Measurement of arterial blood gas shows pH 7.0, PaO2 90 mm Hg, PaCO2 23 mm Hg, and HCO3 12 mmol/L; other results are Na+ 126 mmol/L, K+ 5 mmol/L, and Cl- 95 mmol/L. What is your assessment?', '["Respiratory Acidosis, Uncompensated", "Metabolic Alkalosis, Uncompensated", "Respiratory Acidosis, Partially Compensated", "Metabolic Acidosis, Partially, Compensated"]'::jsonb, 3, 'pH 7.0 with low HCO3⁻ (12) is metabolic acidosis (DKA). The low PaCO2 (23) is partial respiratory compensation.', 'NNP 412 · Applied Biochemistry'),
(1, 57, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Autoclaving is a sterilisation method that primarily uses:', '["Ultraviolet light only", "Cold chemical soaking only, with no heat", "Dry air at room temperature", "Pressurised steam at high temperature"]'::jsonb, 3, 'Autoclaves use pressurised steam at high temperature to achieve sterilisation, effective against even resistant bacterial spores.', 'NNP 412 · Applied Biochemistry'),
(1, 58, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A young woman is found comatose, having taken an unknown number of sleeping pills an unknown time before. An arterial blood sample yields the following values: pH 6.90, HCO3- 13 meq/liter, and PaCO2 68 mmHg. This patient’s acid-base status is most accurately described as:', '["Respiratory Acidosis with Complete Renal Compensation", "Metabolic Acidosis", "Simultaneous Respiratory and Metabolic Acidosis", "Respiratory Acidosis"]'::jsonb, 2, 'pH 6.90 with high PaCO2 (68) AND low HCO3⁻ (13) is combined respiratory and metabolic acidosis.', 'NNP 412 · Applied Biochemistry'),
(1, 59, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Sterilisation, as distinct from disinfection, is defined as a process that:', '["Only reduces the number of organisms, without eliminating any", "Is only relevant to skin antisepsis", "Kills ALL microorganisms, including bacterial spores", "Kills most pathogens but not bacterial spores"]'::jsonb, 2, 'Sterilisation (e.g. via autoclaving) destroys all microorganisms including resistant bacterial spores, unlike disinfection which reduces most pathogens but may not eliminate spores.', 'NNP 412 · Applied Biochemistry'),
(1, 60, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'An ICU patient has pH 7.30, PaCO₂ 30 mmHg, HCO₃⁻ 14 mmol/L, Na⁺ 140 and Cl⁻ 104 mmol/L. The best interpretation is:', '["Normal anion gap metabolic acidosis with respiratory compensation", "High anion gap metabolic acidosis with respiratory compensation", "Primary respiratory alkalosis with renal compensation", "Mixed respiratory acidosis and metabolic alkalosis"]'::jsonb, 1, 'Anion gap = 140 − (104 + 14) = 22, so the gap is high. The low PaCO₂ is the expected compensation.', 'NNP 412 · Applied Biochemistry'),
(1, 61, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Short-term hyperventilation to PaCO₂ 4–4.5 kPa (30–35 mmHg) lowers ICP by:', '["Cerebral vasoconstriction, reducing blood volume", "Increased cerebral blood flow and oxygen delivery", "Dilatation of the cerebral veins and sinuses", "Increased CSF production by the choroid plexus"]'::jsonb, 0, 'Prolonged or excessive hyperventilation risks cerebral ischaemia.', 'NNP 412 · Applied Biochemistry'),
(1, 62, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Before giving an NG feed, the nurse confirms tube position by:', '["Aspirate pH 5.5 or below, or X-ray", "Placing the tube end in a cup of water", "Listening for injected air (whoosh test)", "Asking the patient if it feels right"]'::jsonb, 0, 'The ''whoosh'' test is unreliable.', 'NNP 412 · Applied Biochemistry'),
(1, 63, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient with thrombocytopenia has oozing from IV sites. The nurse prepares to administer:', '["FFP", "Cryoprecipitate", "Platelets", "PRBCs"]'::jsonb, 2, 'Platelets treat thrombocytopenic bleeding.', 'NNP 412 · Applied Biochemistry'),
(1, 64, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'In a patient undergoing surgery, it was vital to aspirate the contents of the upper gastrointestinal tract. After the operation, the following values were acquired from an arterial blood sample: pH 7.55, PCO2 52 mm Hg and HCO3- 40 mmol/l. What is the underlying disorder?', '["Respiratory Acidosis", "Metabolic Acidosis", "Metabolic Alkalosis", "Respiratory Alkalosis"]'::jsonb, 2, 'pH 7.55 (alkalosis) with HCO3⁻ 40 (high) is metabolic alkalosis from loss of gastric acid. The raised PCO2 is respiratory compensation.', 'NNP 412 · Applied Biochemistry'),
(1, 65, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A completely normal pH on an ABG:', '["Only occurs in healthy people", "Does NOT rule out a mixed disorder", "Always rules out any acid-base disorder", "Means PaCO2 and HCO3 must also be normal"]'::jsonb, 1, 'Two opposing disorders (e.g. respiratory acidosis plus metabolic alkalosis) can cancel each other out, producing a falsely reassuring normal pH — always check all three values.', 'NNP 412 · Applied Biochemistry'),
(1, 66, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which one of the following drug is administered every 3-5 minutes of CPR?', '["Epinephrine", "Atropine", "Amiodarone", "Vasopressin"]'::jsonb, 0, 'Epinephrine is re-dosed every 3-5 minutes during resuscitation.', 'NNP 413 · Applied Pharmacology'),
(1, 67, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'If blood glucose levels are low, then epinephrine and glucagon hormones are secreted to stimulate the conversion of glycogen to glucose. This process is called', '["Glycogenolysis", "Glycogenesis", "Glucose formation", "Glucose uptake"]'::jsonb, 0, 'Breaking glycogen back down into glucose is glycogenolysis.', 'NNP 413 · Applied Pharmacology'),
(1, 68, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Poisoning management in the ICU may include gastric lavage, which is most effective when performed:', '["More than 24 hours after ingestion", "Within about 1 hour of ingestion (up to 2–4 hours in some cases), and never in corrosive poisoning", "At any time regardless of the substance ingested", "Only in infants"]'::jsonb, 0, 'Gastric lavage is most useful shortly after ingestion (roughly within 1–4 hours) and is contraindicated in corrosive/caustic poisoning due to perforation risk.', 'NNP 413 · Applied Pharmacology'),
(1, 69, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Gastric lavage is contraindicated in which of the following situations?', '["Within 2 hours of a large tablet overdose", "Corrosive/acid ingestion", "General sedative overdose within 1 hour", "Barbiturate overdose while still conscious"]'::jsonb, 1, 'Passing a tube for a corrosive substance risks further damage to the oesophagus and stomach.', 'NNP 413 · Applied Pharmacology'),
(1, 70, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient receiving dexmedetomidine for sedation may experience:', '["Hypertension and tachycardia", "Respiratory depression", "Agitation", "Bradycardia and hypotension"]'::jsonb, 3, 'Dexmedetomidine (α2-agonist) causes sympatholysis, leading to bradycardia/hypotension.', 'NNP 413 · Applied Pharmacology'),
(1, 71, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A nurse must give a 40 mg IV push dose over 4 minutes. The drug is supplied as 40 mg in 4 mL. At what rate, in mL/min, should the nurse push the medication?', '["0.5 mL/min", "10 mL/min", "1 mL/min", "4 mL/min"]'::jsonb, 2, 'Concentration = 40 mg/4 mL = 10 mg/mL. To deliver 40 mg over 4 minutes = 10 mg/min = 1 mL/min.', 'NNP 413 · Applied Pharmacology'),
(1, 72, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The specific antidote for opioid-induced respiratory depression is:', '["Flumazenil", "Naloxone", "Neostigmine", "Atropine"]'::jsonb, 1, 'Naloxone is a pure opioid antagonist. It has a shorter duration than many opioids, so re-narcotisation can occur and the patient must be observed. Small titrated doses avoid sudden severe pain.', 'NNP 413 · Applied Pharmacology'),
(1, 73, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which of the following is not an ideal characteristic of a volatile anaesthetic agent?', '["Cheap to manufacture", "Flammable", "Safe for all ages and in pregnancy", "Odourless or pleasant to inhale"]'::jsonb, 1, 'Flammability is a dangerous, undesirable property — not an ideal characteristic of a volatile anaesthetic.', 'NNP 413 · Applied Pharmacology'),
(1, 74, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The antidote used to reverse benzodiazepine sedation is:', '["Protamine sulphate", "Flumazenil", "Naloxone", "Acetylcysteine"]'::jsonb, 1, 'Flumazenil blocks the same receptor benzodiazepines act on, though caution is needed in dependent patients.', 'NNP 413 · Applied Pharmacology'),
(1, 75, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A client with asthma is taking a theophylline bronchodilator. Which breakfast item should the nurse discuss with the client?', '["Eggs", "Toast", "Coffee", "Bananas"]'::jsonb, 2, 'Caffeine, like theophylline, is a methylxanthine. Coffee can add to theophylline''s stimulant and toxic effects (tachycardia, tremor).', 'NNP 413 · Applied Pharmacology'),
(1, 76, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A nephrology nurse notes that a patient''s calcium levels are high. Which medication would the nurse anticipate discontinuing?', '["Sevelamer", "Sodium bicarbonate", "Calcitriol", "Erythropoietin"]'::jsonb, 2, 'The correct answer is: Calcitriol.', 'NNP 413 · Applied Pharmacology'),
(1, 77, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient in septic shock requires norepinephrine. Which effect is PRIMARY for this drug?', '["Bronchodilation", "Vasoconstriction", "Increased myocardial contractility", "Renal artery dilation"]'::jsonb, 1, 'Norepinephrine is an α-agonist that increases SVR and MAP in septic shock. Inotropy is secondary.', 'NNP 413 · Applied Pharmacology'),
(1, 78, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient with myasthenia gravis is prescribed neostigmine. The nurse should monitor for:', '["Cholinergic crisis", "Neuroleptic malignant syndrome", "Thyroid storm", "Serotonin syndrome"]'::jsonb, 0, 'Overdose of acetylcholinesterase inhibitors (e.g., neostigmine) causes cholinergic crisis (SLUDGE syndrome).', 'NNP 413 · Applied Pharmacology'),
(1, 79, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient receiving IV insulin for hyperglycemia should be monitored for:', '["Hypermagnesemia", "Hypernatremia", "Hypokalemia", "Hypocalcemia"]'::jsonb, 2, 'Insulin shifts K⁺ intracellularly, causing hypokalemia.', 'NNP 413 · Applied Pharmacology'),
(1, 80, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which inhalational anaesthetic agent has the lowest blood-gas partition coefficient among the following, resulting in the most rapid induction and emergence?', '["Desflurane", "Sevoflurane", "Halothane", "Isoflurane"]'::jsonb, 0, 'Desflurane has a blood:gas partition coefficient of about 0.42, the lowest of the common volatile agents, giving it the fastest onset and offset of action.', 'NNP 413 · Applied Pharmacology'),
(1, 81, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Protamine sulfate is used to reverse the anticoagulant effect of:', '["Aspirin", "Heparin", "Clopidogrel", "Warfarin"]'::jsonb, 1, 'Protamine sulfate binds and neutralises heparin, reversing its anticoagulant effect.', 'NNP 413 · Applied Pharmacology'),
(1, 82, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Basic treatment of acute pancreatitis includes early fluid resuscitation, analgesia, and which of the following', '["NPO (Bowel rest)", "Total parental nutrition", "Antibiotics", "ERCP"]'::jsonb, 0, 'Bowel rest (NPO) is a standard basic component of acute pancreatitis management.', 'NNP 413 · Applied Pharmacology'),
(1, 83, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which of these drugs is used as an antidote for narcotics', '["Cimetidine", "Black charcoal", "Atropine", "Nalaxone"]'::jsonb, 3, 'Naloxone is the antidote for narcotic (opioid) overdose.', 'NNP 413 · Applied Pharmacology'),
(1, 84, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient receiving cyclosporine post-transplant has hypertension. Which drug is CONTRAINDICATED?', '["Amlodipine", "Verapamil", "Lisinopril", "Nifedipine"]'::jsonb, 1, 'Verapamil increases cyclosporine levels via CYP3A4 inhibition, risking toxicity.', 'NNP 413 · Applied Pharmacology'),
(1, 85, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient who has been admitted with a gastric ulcer now develops severe epigastric pain that spreads over the entire abdomen. He is very pale and is lying on his side. What should be the nurse''s immediate action?', '["Reposition the patient in Semi-Fowler''s Position.", "Notify the doctor and check the vitals.", "Perform deep palpations on the abdomen.", "Immediately administer opioids."]'::jsonb, 1, 'Sudden severe abdominal pain with pallor after a known ulcer suggests perforation — notify the doctor and check vitals immediately.', 'NNP 413 · Applied Pharmacology'),
(1, 86, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'In shockable cardiac arrest, the first dose of amiodarone is:', '["300 mg IV after the third shock", "150 mg IV before the first shock", "50 mg IV after every shock", "900 mg IV after the first shock"]'::jsonb, 0, 'A further 150 mg may be given after the fifth shock.', 'NNP 413 · Applied Pharmacology'),
(1, 87, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient on dopamine at 15 mcg/kg/min is likely to experience:', '["Hyperglycemia", "Bronchospasm", "Vasoconstriction", "Renal artery dilation"]'::jsonb, 2, 'High-dose dopamine (>10 mcg/kg/min) activates α-receptors, causing vasoconstriction.', 'NNP 413 · Applied Pharmacology'),
(1, 88, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The oxygen flush valve on an anaesthesia machine delivers pure oxygen directly to the common gas outlet, bypassing the vaporizer, at a flow rate of approximately:', '["5-10 L/min", "1-2 L/min", "100-150 L/min", "35-75 L/min"]'::jsonb, 3, 'The oxygen flush valve delivers oxygen at roughly 35-75 L/min directly from the oxygen supply, bypassing the vaporizers, and should never be activated while the patient is connected to the circuit under positive pressure to avoid barotrauma.', 'NNP 413 · Applied Pharmacology'),
(1, 89, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient presents with pinpoint pupils, respiratory rate of 6 breaths/min, decreased level of consciousness, and bradycardia. Which toxidrome does this most likely represent?', '["Cholinergic toxidrome", "Opioid toxidrome", "Sympathomimetic toxidrome", "Anticholinergic toxidrome"]'::jsonb, 1, 'Miosis (pinpoint pupils), respiratory depression, and CNS depression are the classic triad of opioid toxicity.', 'NNP 413 · Applied Pharmacology'),
(1, 90, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A nurse mistakenly calculates a dopamine infusion using the patient''s weight in pounds (80 lb) instead of converting to kilograms (36.4 kg) first. If the ordered dose is 5 mcg/kg/min with a concentration of 1600 mcg/mL, by roughly what factor will the error inflate the calculated rate compared to the correct rate?', '["Approximately 10 times too high", "Approximately half the correct rate", "Approximately 2.2 times too high", "No difference, the rate is unaffected"]'::jsonb, 2, 'Using pounds instead of kilograms without conversion means the ''weight'' value used is 2.2 times larger than the true kilogram value, so the calculated mcg/min dose (and resulting rate) becomes approximately 2.2 times too high — a dangerous overdose.', 'NNP 413 · Applied Pharmacology'),
(1, 91, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A Nurse in the ER observes that the patient has lost 100 ml of blood in 4 hours. According to the classification of hemorrhage it is;', '["Secondary Hemorrhage", "Primary Hemorrhage", "Acute Hemorrhage", "Chronic hemorrhage"]'::jsonb, 3, 'A small, slow ongoing loss over hours reflects chronic, low-grade bleeding.', 'NNP 413 · Applied Pharmacology'),
(1, 92, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which volatile anaesthetic agent is most associated with sensitizing the myocardium to catecholamines, predisposing to arrhythmias, particularly if epinephrine is administered concurrently?', '["Nitrous oxide", "Desflurane", "Sevoflurane", "Halothane"]'::jsonb, 3, 'Halothane sensitizes the myocardium to circulating catecholamines more than other modern volatile agents, increasing the risk of ventricular arrhythmias when epinephrine-containing solutions are used.', 'NNP 413 · Applied Pharmacology'),
(1, 93, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which of the following is a thrombolytic agent?', '["Heparin", "Clexane (enoxaparin)", "Warfarin sodium", "Streptokinase"]'::jsonb, 3, 'Streptokinase (like alteplase) is a thrombolytic that dissolves clots. Heparin, enoxaparin (Clexane) and warfarin are anticoagulants that only stop clots growing.', 'NNP 413 · Applied Pharmacology'),
(1, 94, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which action should the nurse take when preparing patient-controlled analgesia for a postoperative patient?', '["Instruct the patient to administer a dose only when experiencing pain.", "Provide clear, simple instructions for dosing if the patient is cognitively impaired", "Caution the patient to limit the number of times he presses the dosing button.", "Ask another nurse to double-check the setup before patient use."]'::jsonb, 3, 'Having a second nurse double-check PCA setup is a core safety practice before patient use.', 'NNP 413 · Applied Pharmacology'),
(1, 95, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A drug is available as a 1:10,000 solution, commonly used for cardiac arrest adrenaline. How many milligrams are in a 10 mL prefilled syringe of this solution?', '["100 mg", "10 mg", "1 mg", "0.1 mg"]'::jsonb, 2, 'A 1:10,000 solution = 1 g in 10,000 mL = 0.1 mg/mL. 10 mL x 0.1 mg/mL = 1 mg, the standard cardiac arrest dose.', 'NNP 413 · Applied Pharmacology'),
(1, 96, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which history requires caution when giving paracetamol (acetaminophen)?', '["Allergy to aspirin", "Gastric irritation with bleeding", "Occasional alcohol use", "Hepatitis B"]'::jsonb, 3, 'Paracetamol is metabolised by the liver and is hepatotoxic. Use it with caution in liver disease such as hepatitis B.', 'NNP 413 · Applied Pharmacology'),
(1, 97, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which of these is Not Opioid Analgesic Drug', '["Ketorolac", "Pethidine", "Morphine", "Fentanyl,"]'::jsonb, 0, 'Ketorolac is an NSAID, not an opioid, unlike morphine, pethidine, and fentanyl.', 'NNP 413 · Applied Pharmacology'),
(1, 98, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Patient-controlled analgesia (PCA) is safe mainly because:', '["Relatives and visitors can press the button for the patient", "There is no maximum dose, so pain is always fully relieved", "A sedated patient cannot press, and the lockout limits doses", "It contains no opioid, so respiratory depression cannot occur"]'::jsonb, 2, 'Only the patient may press the demand button. Nurses monitor pain, sedation, respiratory rate, SpO2 and the pump settings regularly.', 'NNP 413 · Applied Pharmacology'),
(1, 99, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Bronchodilator nebulisers (e.g. salbutamol) can cause which common side effect that the nurse should monitor for?', '["Bradycardia and sedation", "Tachycardia and tremor", "Hypoglycaemia", "Weight gain"]'::jsonb, 1, 'Beta-2 agonist bronchodilators commonly cause tachycardia and fine tremor as expected sympathomimetic side effects.', 'NNP 413 · Applied Pharmacology'),
(1, 100, 'Nephrology Nursing Mock — Day 3 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient is prescribed an ACE inhibitor for hypertension. The nurse should monitor for which characteristic side effect?', '["Persistent dry cough", "Hair loss", "Improved potassium excretion with no monitoring needed", "Significant weight gain only"]'::jsonb, 0, 'ACE inhibitors are classically associated with a persistent dry cough (related to bradykinin accumulation), a common reason for switching to an ARB if troublesome.', 'NNP 413 · Applied Pharmacology'),
(2, 1, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A typical blood flow rate for adult haemodialysis through a mature fistula is:', '["1000–1500 mL/min", "250–400 mL/min", "5–10 mL/min", "20–50 mL/min"]'::jsonb, 1, 'Higher flows increase clearance if access allows.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 2, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A thrombosed AV fistula is recognised by:', '["A strong continuous buzz", "Warm, pink skin", "Absent thrill and bruit", "Normal blood flow on dialysis"]'::jsonb, 2, 'Urgent referral for declotting is needed.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 3, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Iron for dialysis patients on ESA is often given:', '["As a blood transfusion every week", "Only by intramuscular injection", "Intravenously during dialysis", "Never, as iron is harmful"]'::jsonb, 2, 'Check ferritin and transferrin saturation.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 4, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'The following are heparin regimens (administration) except', '["Tight/low heparin", "Heparin free", "Low molecular weight free", "Regular or routine"]'::jsonb, 1, 'The correct answer is: Heparin free.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 5, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Hypoglycaemia during haemodialysis is more likely in:', '["Non-diabetics on glucose dialysate", "Patients on insulin pumps that are switched off", "Patients eating during dialysis", "Diabetics using glucose-free dialysate"]'::jsonb, 3, 'Monitor glucose in diabetic patients.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 6, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Dialysate potassium for most stable haemodialysis patients is usually:', '["7 mmol/L", "0 mmol/L in all patients", "2–3 mmol/L", "10 mmol/L"]'::jsonb, 2, 'Very low potassium baths can cause arrhythmias.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 7, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'The main dialysis access recommended as ''Fistula First'' is:', '["Arteriovenous graft in the thigh", "Native arteriovenous fistula", "Temporary femoral catheter", "Peritoneal catheter"]'::jsonb, 1, 'Fistulas last longest with fewest infections.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 8, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'The ''rule of 6s'' for a mature fistula includes a flow of at least 600 mL/min, a depth of less than 6 mm and a diameter of at least:', '["15 mm", "6 mm", "1 mm", "2 mm"]'::jsonb, 1, 'It is ready about 6 weeks after creation.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 9, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Sodium profiling in dialysis is used to:', '["Remove more potassium", "Prevent infection", "Increase thirst between sessions", "Reduce cramps and hypotension during fluid removal"]'::jsonb, 3, 'High final sodium can increase thirst and weight gain.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 10, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Transmembrane pressure (TMP) rising during dialysis may mean:', '["The dialysate is too warm", "The dialyser is clotting or ultrafiltration is high", "The blood flow is too low", "The patient is hypotensive"]'::jsonb, 1, 'Check the circuit and settings.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 11, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Venous needle dislodgement is dangerous because:', '["Blood can be lost rapidly while the pump continues", "Potassium rises sharply", "The patient becomes hypertensive", "The dialysate becomes cool"]'::jsonb, 0, 'Keep the access uncovered and well taped.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 12, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A tunnelled cuffed dialysis catheter has a cuff that:', '["Anchors the catheter and acts as a barrier to infection", "Measures blood pressure", "Delivers heparin automatically", "Prevents clotting completely"]'::jsonb, 0, 'It sits in the subcutaneous tunnel.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 13, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Heparin for haemodialysis anticoagulation is usually given as:', '["A loading dose at the start and an infusion or top-up during dialysis", "Directly into the dialysate", "Only orally the day before", "A single dose after dialysis ends"]'::jsonb, 0, 'Stop the infusion near the end of the session.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 14, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Intradialytic hypertension may be due to:', '["Low dialysate sodium only", "Fluid overload and removal of antihypertensive drugs by dialysis", "Excess ultrafiltration", "Hypoglycaemia"]'::jsonb, 1, 'Reassess dry weight.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 15, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Haemodiafiltration combines:', '["Only diffusion", "Only osmosis", "Peritoneal and haemodialysis together", "Diffusion and convection using replacement fluid"]'::jsonb, 3, 'It clears middle molecules better.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 16, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'The commonest cause of death in dialysis patients is:', '["Hypoglycaemia", "Accidents", "Kidney stones", "Cardiovascular disease"]'::jsonb, 3, 'Control BP, lipids, anaemia and phosphate.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 17, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Venous hypertension after AV access creation presents with:', '["Bradycardia", "Swelling of the arm and hand", "Hypoglycaemia", "Cold, pale fingers"]'::jsonb, 1, 'It may be due to a central vein stenosis.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 18, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A first step in managing intradialytic hypotension is to:', '["Raise the dialysate temperature", "Lower the head, reduce or stop ultrafiltration and give saline if needed", "Sit the patient upright quickly", "Increase the ultrafiltration rate"]'::jsonb, 1, 'Then reassess dry weight.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 19, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'The air detector on the venous line of a dialysis machine prevents:', '["Haemolysis", "Hypotension", "Air embolism by clamping the line", "Clotting"]'::jsonb, 2, 'Never bypass the air detector.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 20, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A water softener in dialysis water treatment removes mainly:', '["Calcium and magnesium", "Glucose", "Bacteria", "Chloramine"]'::jsonb, 0, 'It protects the RO membrane from scaling.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 21, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'The arterial pressure alarm reading becomes more negative when:', '["The venous needle is blocked", "The patient is hypertensive", "The dialysate flow is high", "Blood flow from the access is poor, e.g. the needle is against the vessel wall"]'::jsonb, 3, 'Reposition the needle or reduce blood flow.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 22, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Nocturnal haemodialysis gives:', '["No change at all", "Worse clearance than standard dialysis", "Higher fluid gains", "Better phosphate and blood pressure control"]'::jsonb, 3, 'Sessions of 6–8 hours are done overnight.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 23, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A dialysis nurse notices a patient''s pre-dialysis potassium is 6.8 mmol/L. The nurse should:', '["Inform the doctor, check the ECG and use the right dialysate potassium", "Use a high-potassium bath", "Give oral potassium", "Delay dialysis to tomorrow"]'::jsonb, 0, 'Dialysis lowers potassium effectively.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 24, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A standard adult haemodialysis prescription is usually:', '["About 4 hours, three times a week", "30 minutes daily", "2 hours once a week", "12 hours once a month"]'::jsonb, 0, 'Longer or more frequent dialysis gives better outcomes.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 25, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'The usual dialysate temperature during haemodialysis is about:', '["30 °C", "35.5–37 °C", "25 °C", "40–42 °C"]'::jsonb, 1, 'Too hot causes haemolysis; slightly cool dialysate can reduce hypotension.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 26, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Pre-dialysis assessment by the nurse includes:', '["Weight, BP, pulse, temperature, access check and symptoms since last session", "Only the patient''s name", "Only the dialysate colour", "Nothing if the patient is stable"]'::jsonb, 0, 'This guides ultrafiltration and identifies problems.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 27, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'The ultrafiltration goal for a session is usually set as:', '["Always 5 litres", "Equal to the urine output of the day", "Pre-dialysis weight minus dry weight, plus any fluid given", "Zero for all patients"]'::jsonb, 2, 'Rates above about 13 mL/kg/h increase hypotension risk.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 28, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A new arteriovenous fistula is usually ready for cannulation after about:', '["6 months in all cases", "2 days", "1 week", "6–8 weeks (maturation)"]'::jsonb, 3, 'The ''rule of 6s'' guides maturity.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 29, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Haemostasis after removing fistula needles is best achieved by:', '["No pressure at all", "A tight tourniquet for one hour", "Gentle pressure over the needle site for about 10 minutes without blocking flow", "Very firm pressure that stops the thrill"]'::jsonb, 2, 'Too much pressure can clot the access.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 30, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Chest pain during haemodialysis should be managed by:', '["Reducing blood flow, giving oxygen, doing an ECG and informing the doctor", "Increasing the blood flow", "Ignoring it until the end of the session", "Removing the patient from the chair at once"]'::jsonb, 0, 'Consider myocardial ischaemia, haemolysis or air embolism.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 31, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Uraemic bleeding is treated with dialysis and, if needed:', '["Desmopressin (DDAVP)", "Aspirin", "Heparin", "Warfarin"]'::jsonb, 0, 'Uraemia impairs platelet function.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 32, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Before starting dialysis through a catheter, the nurse should first:', '["Remove the dressing and leave it off", "Inject air to clear the line", "Aspirate and discard the lock solution, then check flow", "Flush the lock into the patient"]'::jsonb, 2, 'This avoids giving a bolus of heparin.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 33, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'When cannulating an AV fistula, the arterial needle is placed:', '["In the opposite arm", "Directly into the anastomosis", "In the radial artery", "At least 3–5 cm from the anastomosis, pointing toward or away as per policy"]'::jsonb, 3, 'Needles are kept apart to reduce recirculation.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 34, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'The nurse should not give which drug just before dialysis without checking, because it is removed by dialysis?', '["Eye drops", "Water-soluble antibiotics such as vancomycin or aminoglycosides", "Topical creams", "Insulin given subcutaneously"]'::jsonb, 1, 'Many drugs are given after dialysis instead.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 35, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A patient''s dialysis access arm should never be used for:', '["Exercise with a soft ball", "Washing with soap and water", "Checking the thrill", "Blood pressure readings, IV cannulas or blood tests"]'::jsonb, 3, 'Protect the access to keep it working.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 36, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Bicarbonate dialysate is preferred to acetate because it:', '["Causes less hypotension and better corrects acidosis", "Needs no water treatment", "Is cheaper and never grows bacteria", "Removes more potassium"]'::jsonb, 0, 'Acetate caused vasodilation and nausea.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 37, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Haemolysis during dialysis is suggested by:', '["Improved blood pressure", "Port-wine coloured blood in the venous line, chest pain and back pain", "Low potassium", "Bright red blood in the circuit"]'::jsonb, 1, 'Stop dialysis and do not return the blood.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 38, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Hypersensitivity to ethylene oxide sterilant in a new dialyser may cause:', '["Muscle cramps at the end", "Bradycardia only", "Anaphylactic first-use reaction early in dialysis", "Late fever after 24 hours"]'::jsonb, 2, 'Rinse dialysers well before use.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 39, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Dialysis patients'' blood pressure should ideally be measured:', '["On the non-access arm", "Only after eating", "On the access arm", "Only on the thigh"]'::jsonb, 0, 'Protect the fistula arm.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 40, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Causes of haemolysis during haemodialysis include:', '["Overheated or hypotonic dialysate, chloramine and kinked lines", "Low ultrafiltration", "Correct conductivity", "Normal dialysate temperature"]'::jsonb, 0, 'Check water and machine settings.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 41, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'An NSAID such as ibuprofen is avoided after surgery in a patient with:', '["Normal kidney and liver function", "A mild tension-type headache after the anaesthetic", "A clean, small surgical wound", "Acute kidney injury or active GI bleeding"]'::jsonb, 3, 'NSAIDs reduce renal blood flow and impair platelets.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 42, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which class of antibiotics is well known for nephrotoxic potential requiring renal dose adjustment and trough level monitoring in ICU patients?', '["Aminoglycosides", "First-generation cephalosporins", "Penicillins", "Macrolides"]'::jsonb, 0, 'Aminoglycosides such as gentamicin accumulate in proximal tubular cells and can cause dose-related acute tubular necrosis; trough levels and renal function must be monitored closely.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 43, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Hemodynamic pressure monitoring provides information about the following parameters:', '["Blood Volume and Heart Rate", "Blood Volume and Stroke Volume", "Fluid balance and Stroke Volume", "Blood volume and fluid balance"]'::jsonb, 3, 'Hemodynamic monitoring reflects the patient''s circulating blood volume and fluid balance status.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 44, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Vibration, as an airway clearance technique, is applied:', '["Only during coughing", "During inspiration only", "Throughout the whole breathing cycle", "During expiration only"]'::jsonb, 3, 'Vibration is timed to the outward breath, helping shake secretions loose as air moves out.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 45, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The peak inspiratory pressure safety limit during mechanical ventilation for asthma is:', '["<60cmH2O", "<20cmH2O", "<40cmH2O", "No limit needed"]'::jsonb, 2, 'Exceeding this pressure risks rupturing the already overinflated, fragile lungs.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 46, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient''s ECG shows ST-segment depression in the anterior leads during an episode of chest pain, which resolves when the pain resolves. This pattern most likely represents:', '["Myocardial ischaemia", "Old, resolved myocardial infarction with no current significance", "Ventricular hypertrophy only", "Normal variant with no clinical significance"]'::jsonb, 0, 'Transient ST depression correlating with chest pain onset and resolution is a hallmark of myocardial ischaemia.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 47, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Abnormal flexion (decorticate posturing) corresponds to which motor score on the Glasgow Coma Scale?', '["5", "4", "3", "6"]'::jsonb, 2, 'Decorticate (abnormal flexor) posturing is scored as a motor response of 3 on the GCS, worse than localizing (5) or withdrawal (4) but better than extensor posturing (2).', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 48, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Pulmonary oedema is the.........', '["Active movement of fluid across alveolar venous membrane into the alveoli", "Active movement of fluid across the capillary membrane into the alveoli", "Active movement of fluid across alveolar arterial membrane into the alveoli.", "Active movement of fluid across the heart to the lungs."]'::jsonb, 1, 'Pulmonary oedema is fluid actively moving across the capillary membrane into the alveoli.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 49, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A post-operative patient who has not passed urine for 8 hours with lower abdominal discomfort most likely has:', '["Urinary retention", "Normal post-operative state", "Fluid overload", "Acute renal failure in all cases"]'::jsonb, 0, 'Bladder scanning confirms retention. Causes include opioids, spinal anaesthesia, anticholinergics and pain. Catheterisation may be needed.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 50, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Hypertension is the leading cause of end-stage renal disease after which condition?', '["Hepatitis", "Asthma", "Diabetes", "Osteoarthritis"]'::jsonb, 2, 'Diabetes is the single leading cause, with hypertension close behind as the second most common cause of ESRD.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 51, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which of the following finding would indicate the presence of myocardial infarction?', '["Decreased WBC level", "Increased blood urea nitrogen level", "Increased creatinine kinase MB", "Increased serum potassium"]'::jsonb, 2, 'CK-MB is a cardiac-specific enzyme that rises with myocardial injury.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 52, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Manual hyperoxygenation before suction is used to:', '["Prevent hypoxaemia during suction", "Increase the CO₂ level in the blood", "Reduce the cardiac output and heart rate", "Help to remove the endotracheal tube"]'::jsonb, 0, '100% oxygen for 30–60 seconds is common.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 53, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Acute kidney injury caused by renal artery stenosis reducing blood flow to the kidney is classified as:', '["Prerenal", "Postrenal", "Intrinsic (renal)", "Not a cause of AKI"]'::jsonb, 0, 'Prerenal AKI results from reduced blood flow reaching the kidneys (e.g. hypovolaemia, hypotension, renal artery stenosis) before intrinsic kidney damage occurs.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 54, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Humidification of inspired gases during ventilation for asthma is used to:', '["Cause bronchospasm", "Increase airway resistance", "Reduce thick secretions", "Replace the need for bronchodilators"]'::jsonb, 2, 'Moist air helps keep mucus thinner and easier to clear, reducing the risk of mucus plugging.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 55, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The classic triad seen in Amniotic Fluid Embolism is:', '["Headache, blurred vision, hypertension", "Jaundice, ascites, confusion", "Hypotension, hypoxia, DIC", "Fever, rash, joint pain"]'::jsonb, 2, 'AFE causes a sudden collapse pattern combining low blood pressure, poor oxygenation, and abnormal clotting.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 56, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A 36 year old male patient is diagnosed with acute kidney injury. The patient is voiding 4 L/day of urine. What complication can arise based on the stage of AKI this patient is in? Select all that apply:', '["Hyperkalemia", "High urine specific gravity", "Water intoxication", "Hypotension"]'::jsonb, 2, 'High urine output (polyuric phase of AKI) risks water intoxication/electrolyte loss if not managed carefully.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 57, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Too-rapid correction of chronic hyponatraemia can cause:', '["Acute intracerebral haemorrhage", "Osmotic demyelination syndrome", "Pulmonary oedema and hypoxia", "Severe hyperkalaemia and arrhythmia"]'::jsonb, 1, 'It causes quadriparesis, dysarthria and ''locked-in'' syndrome.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 58, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'For a cancer nephrectomy performed laparoscopically, the kidney must be removed:', '["Whole, inside a protective bag", "Broken into pieces through small incisions", "Through the mouth", "Left inside the body"]'::jsonb, 0, 'Removing the kidney whole, contained in a bag, prevents cancer cells from spreading during extraction.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 59, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient develops fever, tachycardia, tachypnoea, and hypotension not responding to an initial fluid bolus, with a known urinary tract infection. This presentation is most consistent with:', '["Simple dehydration", "Cardiogenic shock", "Anxiety attack", "Septic shock"]'::jsonb, 3, 'Fever with hypotension refractory to fluids in the setting of a known infection source is consistent with septic shock, requiring urgent sepsis bundle management.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 60, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient with hypermagnesemia (Mg²⁺ 4.5 mg/dL) has hypotension and absent deep tendon reflexes. Which intervention is MOST appropriate?', '["Start furosemide 40 mg IV", "Administer magnesium sulfate IV", "Infuse 0.9% normal saline bolus", "Give calcium chloride 10% IV"]'::jsonb, 3, 'Calcium antagonizes magnesium’s effects on neuromuscular and cardiovascular systems. Saline boluses and diuretics support excretion but do not directly counteract toxicity.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 61, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which pulse should the nurse palpate during rapid assessment of an unconscious male adult?', '["Femoral", "Carotid", "Radial", "Brachial"]'::jsonb, 1, 'In an unconscious adult, check the carotid pulse. It persists when peripheral pulses are lost.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 62, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which serum marker is increasingly used as an earlier and more specific indicator of reduced GFR than creatinine, particularly in patients with reduced muscle mass?', '["Troponin", "Cystatin C", "C-reactive protein", "Alkaline phosphatase"]'::jsonb, 1, 'Cystatin C is produced at a constant rate by nucleated cells and is less affected by muscle mass, age, or sex than creatinine, offering a more sensitive early marker of declining GFR.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 63, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'This type of manual ventilation bag is routinely being used during patient''s resuscitation', '["Self-inflating bag", "Flow inflating bag", "Semi-flow inflating bag", "Semi-self-inflating bag"]'::jsonb, 0, 'The self-inflating bag is the standard manual resuscitation device used during CPR.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 64, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which is NOT a nursing priority in BPH?', '["Promotion of urinary incontinence", "Collaboration for diagnostic tests and treatment", "Pain management", "Assessment of urinary symptoms and flow"]'::jsonb, 0, 'BPH priorities: pain, assessing urinary symptoms, and collaborating on investigations. Promoting incontinence is never a goal.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 65, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Hypophosphataemia in ICU may cause:', '["Tetany only, without any muscle weakness", "Hypercalcaemia with kidney stones and polyuria", "Respiratory muscle weakness and failed weaning", "Severe hypertension with headache and blurring"]'::jsonb, 2, 'Common in refeeding and DKA treatment.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 66, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'This is an acute event involving the cardiorespiratory system causing reduced or absent conscious level at any point during pregnancy and 6 weeks postpartum.', '["Maternal collapse", "Morning blues", "Acute syndrome", "Postpartum haemorrhage"]'::jsonb, 0, 'A sudden reduced/absent consciousness event during pregnancy or the postpartum period is termed maternal collapse.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 67, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which agent is NOT used to produce induced (controlled) hypotension during surgery?', '["Esmolol", "Sodium nitroprusside", "Hydralazine", "Mephentermine"]'::jsonb, 3, 'Esmolol, hydralazine and sodium nitroprusside lower BP. Mephentermine is a sympathomimetic vasopressor that raises it.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 68, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'In pre-renal AKI, urine tests usually show:', '["Muddy brown granular casts", "Urine Na⁺ above 40 mmol/L and FENa above 2%", "Urine Na⁺ below 20 mmol/L and FENa below 1%", "Red cell casts and heavy proteinuria"]'::jsonb, 2, 'The kidney is holding sodium. Tubular damage (ATN) gives high urine sodium and FENa.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 69, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Low sodium levels is termed _______', '["Hypo-sodiumaemia", "Hyponatremia", "Hyper- sodiumaemia", "Hypokalemia"]'::jsonb, 1, 'Low sodium is hyponatraemia.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 70, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient with hyperphosphatemia (PO₄³⁻ 7.0 mg/dL) is at risk for which electrolyte imbalance?', '["Hypercalcemia", "Hypernatremia", "Hypocalcemia", "Hypermagnesemia"]'::jsonb, 2, 'Hyperphosphatemia binds calcium, leading to hypocalcemia and tetany.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 71, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A woman with severe mitral stenosis and mitral regurgitation has a pulmonary artery catheter inserted. The physician orders pulmonary artery pressure monitoring, including pulmonary capillary wedge pressures. The purpose of this is to help assess the:', '["Oxygen and carbon dioxide concentration is the blood.", "Degree of coronary artery stenosis.", "Peripheral arterial pressure.", "Pressure from fluid within the left ventricle."]'::jsonb, 3, 'PCWP estimates left atrial pressure and so left ventricular filling (end-diastolic) pressure.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 72, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The fluid that passes through the lymphatic vessels', '["Moves in a single direction toward the heart", "Passes from the lymphatic vessels into the arteries", "Flows toward the lungs", "Enters the left ventricle of the heart through the right thoracic duct"]'::jsonb, 0, 'Lymph moves in one direction, toward the heart, through the lymphatic system.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 73, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'After a burn, a client has BP 70/40, HR 140, RR 25, pallor and weak pedal pulses. The nurse''s first action is to:', '["Obtain an ECG", "Obtain a complete blood count", "Start intravenous fluids", "Check pulses with a Doppler"]'::jsonb, 2, 'Hypotension, tachycardia, pallor and weak pulses after a burn mean hypovolaemic (burn) shock. Start IV fluid resuscitation first.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 74, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'During spontaneous breathing, the pressure in the pleural space remains ...... in inspiration and ...... in expiration?', '["Negative, negative", "Positive, negative", "Positive, positive", "Negative, positive"]'::jsonb, 0, 'Pleural pressure remains negative throughout both inspiration and expiration in normal breathing (becoming more negative on inspiration).', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 75, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient in the ICU develops signs of urinary retention postoperatively. What intervention should the nurse implement?', '["Initiate physical therapy", "Administer stool softeners", "Encourage increased fluid intake", "Insert a urinary catheter"]'::jsonb, 3, 'Bladder catheterisation drains the retained urine when a patient cannot void, relieving bladder distension.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 76, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Energy intake recommended for most stable dialysis patients is about:', '["5 kcal/kg/day", "10–15 kcal/kg/day", "50–60 kcal/kg/day", "30–35 kcal/kg/day"]'::jsonb, 3, 'Adequate energy prevents protein being used for fuel.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 77, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', '______ is providing nutritional intake to a patient who is unable to feed/restricted from feeding via mouth.', '["NG Tube feeding", "OG Tube feeding", "Parenteral nutrition", "Artificial nutrition"]'::jsonb, 3, 'The correct answer is: Artificial nutrition.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 78, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'For patients with CKD, which nutrient is often monitored due to its role in kidney stone formation?', '["Vitamin D", "Iron", "Calcium", "Protein"]'::jsonb, 2, 'Excessive calcium intake can contribute to kidney stones, so it is monitored in', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 79, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Saturated fats are also called ______', '["Vegetable oil", "Plant fat", "Animal fat", "Cholesterol"]'::jsonb, 2, 'The correct answer is: Animal fat.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 80, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', '______ is a strategy designed to bridge the gap between Average Daily Intake (ADI) and the Recommended Dietary Allowance (RDA) by providing additional calories/energy, protein and micronutrients to children', '["Nutrition and dietetics", "Nutritional screening", "Artificial nutrition", "Supplementary nutrition"]'::jsonb, 3, 'The correct answer is: Supplementary nutrition.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 81, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Educating patients with CKD about daily weight monitoring helps them detect:', '["Proteinuria levels", "Changes in blood pressure", "Blood sugar fluctuations", "Fluid overload or dehydration"]'::jsonb, 3, 'The correct answer is: Fluid overload or dehydration.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 82, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Star fruit should be avoided by patients with kidney failure because it:', '["Is too low in potassium", "Contains a neurotoxin that the kidneys cannot clear", "Is high in iron", "Causes kidney stones only in children"]'::jsonb, 1, 'It can cause confusion and seizures.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 83, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Leaching (soaking and boiling) vegetables before cooking helps CKD patients by:', '["Adding phosphate", "Reducing their potassium content", "Increasing their protein", "Increasing sodium"]'::jsonb, 1, 'Discard the water after boiling.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 84, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Patients with CKD are often advised to limit protein intake because:', '["It slows kidney disease progression", "It reduces muscle mass", "It increases blood sugar", "It increases potassium"]'::jsonb, 0, 'The correct answer is: It slows kidney disease progression.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 85, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'The provision of all nutrients in both kind and amount which is the cornerstone of good health and cutting edge of prevention is ______', '["Human nutrition", "Optimum nutrition", "Nutrition", "Balance diet"]'::jsonb, 1, 'The correct answer is: Optimum nutrition.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 86, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Salt intake for most CKD patients should be limited to about:', '["Exactly 30 g per week", "15 g of salt per day", "Less than 5 g of salt (2 g sodium) per day", "No limit at all"]'::jsonb, 2, 'Less salt helps BP and thirst control.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 87, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Hidden phosphate in processed foods and cola drinks matters in CKD because it:', '["Lowers calcium safely", "Is almost fully absorbed and raises serum phosphate", "Protects the bones", "Is never absorbed"]'::jsonb, 1, 'Read food labels for ''phos'' additives.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 88, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'An essential aspect of patient education for CKD patients is:', '["Avoiding all medications", "Reducing protein intake to preserve kidney function", "Encouraging high fluid intake", "Reducing physical activity"]'::jsonb, 1, 'Lower protein intake can help manage CKD progression by reducing kidney', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 89, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'A dialysis patient''s thirst can be reduced by:', '["Eating salty snacks", "Limiting salt, sucking ice cubes or sour sweets, and good sugar control", "Drinking large volumes at once", "Using more salt in cooking"]'::jsonb, 1, 'Salt drives thirst.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 90, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Dietary therapy has not only become an essential adjunct of care but the bedrock of treatment in some critical illnesses like............., hypertension and chronic kidney disease.', '["Nutrition", "Sepsis", "Head injury", "Diabetes"]'::jsonb, 3, 'Dietary therapy is foundational in managing diabetes alongside hypertension and CKD.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 91, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'To reduce aspiration risk during nasogastric tube feeding, the head of bed should be maintained at:', '["Elevated 30–45 degrees", "Prone position", "Flat, 0 degrees", "Trendelenburg position"]'::jsonb, 0, 'Elevating the head of bed 30–45 degrees during and after enteral feeding reduces the risk of gastric reflux and aspiration.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 92, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'A patient develops signs of nutritional deficiencies postoperatively. What intervention should the nurse prioritize?', '["Initiating total parenteral nutrition (TPN)", "Administering vitamin supplements", "Consulting a dietitian", "Ordering a protein-rich diet"]'::jsonb, 2, 'A dietitian consultation supports individualised nutritional assessment and repletion planning for a patient with postoperative nutritional deficiency.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 93, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'A patient''s enteral feed provides 60 g carbohydrate, 20 g protein, and 15 g fat per serving. Using standard Atwater factors, approximately how many total kilocalories does this serving provide?', '["605 kcal", "455 kcal", "395 kcal", "275 kcal"]'::jsonb, 1, 'Calculation: (60 g CHO x 4) + (20 g protein x 4) + (15 g fat x 9) = 240 + 80 + 135 = 455 kcal.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 94, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'A comprehensive nutritional assessment typically integrates which four broad components?', '["Body weight and height only, used to calculate the BMI", "Vital signs, medication list, allergy history and resuscitation status", "Blood pressure, pulse, respiratory rate and core temperature", "Anthropometry, biochemistry, clinical examination and dietary history"]'::jsonb, 3, 'The classic ''ABCD'' framework of nutritional assessment includes Anthropometric measurements, Biochemical/laboratory data, Clinical examination, and Dietary history, providing a comprehensive picture of nutritional status.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 95, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Which of the following macronutrients in parenteral nutrition may need to be increased in a patient who has large, nonhealing wounds?', '["Lipids", "Protein", "Trace elements", "Carbohydrates"]'::jsonb, 1, 'Protein needs rise substantially with large non-healing wounds to support tissue repair.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 96, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'During insertion of a subclavian central line for TPN, the patient suddenly develops sharp chest pain, dyspnea, and decreased breath sounds on the affected side. The nurse should suspect:', '["Catheter occlusion", "Hyperglycemia", "Pneumothorax", "Air embolism"]'::jsonb, 2, 'Pneumothorax is a recognized mechanical complication of subclavian or internal jugular central line placement, presenting with sudden chest pain, dyspnea, and diminished breath sounds on the affected side.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 97, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'The nurse is monitoring a patient on TPN. Which of the following is an early sign of a catheter-related blood stream infection (CRBSI)?', '["Hypocalcemia", "Hyperglycemia", "Refeeding syndrome", "Fever and chills"]'::jsonb, 3, 'Fever and chills are classic systemic signs of infection and should prompt an investigation for a CRBSI. Hyperglycemia can occur for other reasons, and refeeding syndrome is a metabolic complication, not an infection.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 98, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'A nurse finds the TPN bag has been hanging for 26 hours. The most appropriate nursing action is to:', '["Slow the infusion rate until the new bag arrives", "Discard the current bag and obtain a new one", "Continue the infusion as it is still safe", "Clamp the line and flush it with saline"]'::jsonb, 1, 'TPN solutions are a high-risk medium for bacterial growth. They should be changed every 24 hours to prevent the risk of a central line-associated bloodstream infection (CLABSI). The current bag should be discarded and a new one obtained.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 99, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Which nutritional measure helps manage MODS?', '["A very high carbohydrate diet", "High-dose vitamin C alone", "Providing early enteral feeds", "Limiting all fluids"]'::jsonb, 2, 'Early enteral feeding supports gut integrity, reduces bacterial translocation and meets high metabolic demands in MODS.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 100, 'Nephrology Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'In the trauma patient, which route of nutrition support is generally preferred over parenteral nutrition when the gastrointestinal tract is functional, primarily because of superior outcomes related to gut integrity?', '["Parenteral nutrition", "Intravenous dextrose alone", "Oral rehydration solution alone", "Enteral nutrition"]'::jsonb, 3, 'When the GI tract is functional, enteral nutrition is preferred because it maintains gut mucosal integrity, supports gut-associated immune function, and is associated with fewer infectious complications compared with parenteral nutrition.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(3, 1, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Adjustment to a diagnosis of kidney failure often follows stages similar to:', '["Piaget''s stages of cognition", "Freud''s psychosexual stages", "Kübler-Ross stages of grief", "Maslow''s stages of digestion"]'::jsonb, 2, 'Denial, anger, bargaining, depression and acceptance.', 'GST 401 · Applied Psychology & Sociology'),
(3, 2, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'There are various determinants/factors that enhance good interpersonal relationship and such include the following except', '["Empathy", "Fidelity", "Unconditional positive regard", "Compassion"]'::jsonb, 1, 'The correct answer is: Fidelity.', 'GST 401 · Applied Psychology & Sociology'),
(3, 3, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', '__________________Is not among the general adaptation syndrome', '["Exhaustion", "Continuity", "Alarm reaction", "Resistance"]'::jsonb, 1, 'The correct answer is: Continuity.', 'GST 401 · Applied Psychology & Sociology'),
(3, 4, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A coping strategy focused on solving the problem is called:', '["Denial", "Problem-focused coping", "Emotion-focused avoidance only", "Projection"]'::jsonb, 1, 'Emotion-focused coping manages feelings.', 'GST 401 · Applied Psychology & Sociology'),
(3, 5, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Agenda setting theory of communication is mostly used in the ?', '["Nursing education", "Nursing care", "Meeting", "Press and media"]'::jsonb, 3, 'The correct answer is: Press and media.', 'GST 401 · Applied Psychology & Sociology'),
(3, 6, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'The theory of needs was attributed to', '["Henry Fayol", "Abraham Maslow", "Charles Babbage", "Fedrick Herzberg"]'::jsonb, 1, 'The correct answer is: Abraham Maslow.', 'GST 401 · Applied Psychology & Sociology'),
(3, 7, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'The communication model which sees communication as an endless spiral of increasing complexity was founded by ??????', '["Frank Dance 1967", "Dr. Maxwell McCombs and Dr. Donald Lewis Shaw", "Osgood and Schramm 1950", "Shannon and Weaver 1949"]'::jsonb, 0, 'The correct answer is: Frank Dance 1967.', 'GST 401 · Applied Psychology & Sociology'),
(3, 8, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'With regard to communication,facilitation is a form of ?', '["Non-verbal communication", "Verbal communication", "Rapport building", "Spiral communication"]'::jsonb, 1, 'The correct answer is: Verbal communication.', 'GST 401 · Applied Psychology & Sociology'),
(3, 9, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Which of the following definitions of Sociology is more acceptable? It can be defined as:', '["Social behaviour, society, patterns of social relationships and interaction among people", "Societal change and culture that surround everyday life", "Science and art of human customs", "Social science that uses only methods of empirical investigation and critical analysis"]'::jsonb, 2, 'The correct answer is: Science and art of human customs.', 'GST 401 · Applied Psychology & Sociology'),
(3, 10, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A nurse stating that she loves working in long-term care because she likes the elderly population is an example of:', '["Fidelity", "Values", "Respect", "Dignity"]'::jsonb, 1, 'The correct answer is: Values.', 'GST 401 · Applied Psychology & Sociology'),
(3, 11, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Peer support groups for dialysis patients mainly help by:', '["Replacing medical treatment", "Sharing experience and reducing isolation", "Avoiding all family contact", "Lowering potassium"]'::jsonb, 1, 'Patients learn coping skills from each other.', 'GST 401 · Applied Psychology & Sociology'),
(3, 12, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Caregiver burden in families of dialysis patients can be reduced by:', '["Respite care, education and support groups", "Ignoring the caregiver", "Giving the caregiver more tasks", "Stopping hospital visits"]'::jsonb, 0, 'Assess caregivers regularly.', 'GST 401 · Applied Psychology & Sociology'),
(3, 13, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Sick role theory (Parsons) states that the sick person must:', '["Hide the illness", "Try to get well and seek medical help", "Refuse all treatment", "Stay ill to avoid work"]'::jsonb, 1, 'In return they are excused normal duties.', 'GST 401 · Applied Psychology & Sociology'),
(3, 14, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A family is the primary group because it:', '["Is a large formal organisation", "Meets once a year", "Has written rules only", "Provides close, personal and lasting relationships"]'::jsonb, 3, 'Families give care and support.', 'GST 401 · Applied Psychology & Sociology'),
(3, 15, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Cultural beliefs may lead some patients to:', '["Never use any medicine", "Always accept dialysis at once", "Seek traditional healers before or instead of hospital care", "Refuse all food"]'::jsonb, 2, 'Respect beliefs while giving clear information.', 'GST 401 · Applied Psychology & Sociology'),
(3, 16, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Socialisation is the process by which:', '["Cells divide", "People learn the norms and values of their society", "Drugs are absorbed", "Kidneys filter blood"]'::jsonb, 1, 'Illness can disrupt social roles.', 'GST 401 · Applied Psychology & Sociology'),
(3, 17, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Body image disturbance in a dialysis patient may be caused by:', '["Normal blood pressure", "Regular exercise", "Good appetite", "A visible fistula, catheter or PD tube"]'::jsonb, 3, 'Support and counselling help acceptance.', 'GST 401 · Applied Psychology & Sociology'),
(3, 18, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Depression in dialysis patients is important because it is linked to:', '["Lower blood pressure", "Faster recovery", "Poor adherence, more admissions and higher mortality", "Better outcomes"]'::jsonb, 2, 'Screen and refer for treatment.', 'GST 401 · Applied Psychology & Sociology'),
(3, 19, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Social support for dialysis patients is linked to:', '["Better adherence and quality of life", "Higher potassium", "More infections", "Worse outcomes"]'::jsonb, 0, 'Encourage family and peer support.', 'GST 401 · Applied Psychology & Sociology'),
(3, 20, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A patient on long-term dialysis loses their job. This affects mainly their:', '["Blood group", "Role function and self-esteem", "Height", "Eye colour"]'::jsonb, 1, 'Refer to social services and counselling.', 'GST 401 · Applied Psychology & Sociology'),
(3, 21, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Stigma means:', '["Negative labelling and rejection of a person because of a condition", "A type of medicine", "Social acceptance", "A kidney test"]'::jsonb, 0, 'Education reduces stigma.', 'GST 401 · Applied Psychology & Sociology'),
(3, 22, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A defence mechanism in which a patient refuses to accept a diagnosis is:', '["Regression", "Sublimation", "Projection", "Denial"]'::jsonb, 3, 'Nurses allow time and provide support.', 'GST 401 · Applied Psychology & Sociology'),
(3, 23, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Preoperative anxiety can be reduced by:', '["Information, listening and reassurance", "Shouting instructions so they are heard", "Ignoring the patient until induction", "Withholding information about surgery"]'::jsonb, 0, 'Anxiety increases pain and anaesthetic requirements.', 'GST 401 · Applied Psychology & Sociology'),
(3, 24, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A nurse is caring for a client who is in acute respiratory distress and also expressing anxiety about an upcoming diagnostic test. Using Maslow''s hierarchy to prioritize care, the nurse should address which need FIRST?', '["The client''s anxiety about the diagnostic test (safety/psychological need)", "The client''s airway and oxygenation status (physiological need)", "The client''s need for self-esteem and a sense of accomplishment", "The client''s need for social interaction with family"]'::jsonb, 1, 'Physiological needs, including oxygenation, take priority over higher-level needs such as psychological safety or emotional reassurance according to Maslow''s hierarchy, making airway/breathing the first priority.', 'GST 401 · Applied Psychology & Sociology'),
(3, 25, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Stress in theatre staff can be reduced by:', '["Increasing the workload to build strength", "Ignoring feelings so work continues", "Blaming others when things go wrong", "Teamwork, adequate breaks and support"]'::jsonb, 3, 'Debriefing after critical incidents helps.', 'GST 401 · Applied Psychology & Sociology'),
(3, 26, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'CT scan and ultrasound machines are best classified as which type of healthcare ICT device?', '["Monitoring devices only", "Treatment devices only", "Communication devices", "Diagnostic devices"]'::jsonb, 3, 'CT and ultrasound are used to establish or confirm a diagnosis by producing images of internal structures, making them diagnostic devices.', 'GST 402 · Information Communication Technology'),
(3, 27, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'The four main functional components of a standard computer are:', '["Input, process, output and memory (storage)", "Keyboard, mouse, monitor and CPU", "Hardware, software, system apps and applications", "Laptop, desktop, tablet and hand-held"]'::jsonb, 0, 'A computer''s four main functional components are input, processing, output and storage (memory).', 'GST 402 · Information Communication Technology'),
(3, 28, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'Multi-processing in a computer file system refers to the ability to:', '["Process only one task at a time, strictly in sequence", "Only work with a single connected device", "Handle multiple processing tasks concurrently", "Never process data outside business hours"]'::jsonb, 2, 'Multi-processing capability allows a system to handle several processing tasks concurrently, improving efficiency for multi-user hospital systems.', 'GST 402 · Information Communication Technology'),
(3, 29, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'A barcode scanning system in theatre helps to:', '["Replace the need for swab and instrument counts", "Track instruments, implants and drugs accurately", "Increase errors by adding extra steps to the work", "Avoid any documentation of implants and drugs"]'::jsonb, 1, 'It supports traceability.', 'GST 402 · Information Communication Technology'),
(3, 30, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'Which of the following units of data is the largest?', '["Megabyte (MB)", "Kilobyte (KB)", "Terabyte (TB)", "Gigabyte (GB)"]'::jsonb, 2, 'A Terabyte is the largest unit listed, equal to about one trillion bytes. The order from smallest to largest is: Kilobyte (about one thousand bytes), Megabyte (about one million bytes), Gigabyte (about one billion bytes), and Terabyte.', 'GST 402 · Information Communication Technology'),
(3, 31, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'Identify the five main components of a computer system in their order?', '["CPU, Memory, System bus, Input, Output", "Modem, Keyboard, Word Processor, Printer, Screen", "Memory, Video card, Monitor, Software, Hardware", "CPU, CD-ROM, Mouse, Keyboard, Sound card"]'::jsonb, 0, 'CPU, memory, system bus, input, and output are the five core computer system components.', 'GST 402 · Information Communication Technology'),
(3, 32, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'During electronic health documentation, which computer part allows a critical care nurse to enter patient data?', '["Input device", "Operating system", "Software", "Output device"]'::jsonb, 0, 'Input devices (keyboard, mouse, touchscreen, scanner) put data into the computer. Output devices (monitor, printer) display it.', 'GST 402 · Information Communication Technology'),
(3, 33, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'The central processing unit (CPU) of a computer is the:', '["Printer used to produce paper copies", "Part that carries out instructions", "Display screen showing the output", "Keyboard used to type in data"]'::jsonb, 1, 'Memory stores data; input/output devices interact with users.', 'GST 402 · Information Communication Technology'),
(3, 34, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'What is the purpose of an Electronic Health Record (EHR)?', '["To create a digital version of a patient''s chart", "To replace the need for any patient-nurse interaction", "To store only the patient''s demographic information", "To serve as a paper-based filing system"]'::jsonb, 0, 'The EHR is a digital version of a patient’s paper chart. It includes a comprehensive record of a patient’s medical history, diagnoses, medications, treatment plans, immunization dates, allergies, radiology images, and lab and test results.', 'GST 402 · Information Communication Technology'),
(3, 35, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'In data transfer process, what does FTP stand for?', '["File transfer protection", "File transfer program", "File transmission protocol", "File transfer Protocol"]'::jsonb, 3, 'FTP is File Transfer Protocol, a standard way of moving files between computers over a network.', 'GST 402 · Information Communication Technology'),
(3, 36, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'Which of the following is an example of an Internet browser?', '["Notepad", "Internet Explorer", "Internet Navigator", "Microsoft Word"]'::jsonb, 1, 'A web browser (Internet Explorer, Chrome, Firefox, Edge) is software for viewing websites. Notepad and Word are text editors.', 'GST 402 · Information Communication Technology'),
(3, 37, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'ONE OF THESE IS NOT AN ADVANTAGE OF COMPUTER FILES', '["it is hard to use", "It is relatively easy to reproduce or duplicate", "it offers faster access and retrieval of data", "it enhances security of data if proper precautions are taken"]'::jsonb, 0, 'Computer files are easy to copy, secure when protected, and quick to retrieve. Being "hard to use" is not an advantage.', 'GST 402 · Information Communication Technology'),
(3, 38, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'An advantage of the electronic medication administration record (eMAR) over paper MARs is:', '["It requires no cross-check with the pharmacy system", "It cannot be updated in real time", "It eliminates the need for the five rights of administration", "Real-time updates and reduced transcription error risk"]'::jsonb, 3, 'eMAR systems update in real time and are typically integrated with pharmacy and BCMA systems, reducing transcription errors compared to handwritten paper MARs.', 'GST 402 · Information Communication Technology'),
(3, 39, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'A barcode scanner used for patient identification is an example of:', '["A processing device", "A storage device", "An input device", "An output device"]'::jsonb, 2, 'Output devices include printers, monitors and speakers.', 'GST 402 · Information Communication Technology'),
(3, 40, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'A cardiac monitor and pulse oximeter used in the ICU are examples of which category of electronic devices in healthcare?', '["Monitoring devices", "Storage devices", "Treatment devices", "Diagnostic devices"]'::jsonb, 0, 'Cardiac monitors and pulse oximeters continuously track a patient''s physiological status, placing them in the monitoring devices category.', 'GST 402 · Information Communication Technology'),
(3, 41, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which is NOT one of Fayol''s 14 principles of management?', '["Decentralisation", "Scalar chain (clear line of authority)", "Remuneration", "Subordination of individual interests"]'::jsonb, 0, 'Fayol''s principles include subordination of individual interest, remuneration and the scalar chain (clear line of authority). His principle is centralisation, not decentralisation.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 42, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which is a quality of a good plan?', '["Unlimited in time", "Unrealistic", "Vague", "Specific"]'::jsonb, 3, 'A good plan is specific, measurable, achievable, realistic and time-bound (SMART).', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 43, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which of the following characterize a manager as being efficient?', '["They interview, select, and train people who are most suitable to fill open jobs.", "They achieve their goals.", "They use a minimum amount of resources for the amount of outputs produced.", "The devote a large amount of time to planning"]'::jsonb, 2, 'Efficiency means using the fewest resources for a given output.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 44, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'What are the rules of proper conduct among a group of people, such as religion or profession', '["Ethics", "Morals", "Morality", "Values"]'::jsonb, 0, 'Ethics refers to the accepted rules of proper conduct within a group, profession, or society.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 45, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', '"Quality is defined by the customer" is', '["An unrealistic definition of quality", "A product-based definition of quality", "A user-based definition of quality", "A manufacturing-based definition of quality"]'::jsonb, 2, '"Quality is defined by the customer" is a user-based definition of quality.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 46, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Management by Objectives concept was developed by -------.', '["None", "Peter.F.Drucker", "Chester Bernard", "Fayol"]'::jsonb, 1, 'Peter F. Drucker introduced MBO in The Practice of Management (1954).', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 47, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Planning and control functions of a manager are positively correlated', '[".................................. Is the proponent of 14 principles of administration?", "True", "Peter Drucker", "False"]'::jsonb, 1, 'Planning and control functions work together (positively correlated) in effective management.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 48, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', '"The organisation is a complex whole with parts working together like the human body." Which theory fits this statement?', '["Classical theory", "Systems theory", "Humanist theory", "Human relations theory"]'::jsonb, 1, 'Systems theory sees the organisation as a complex whole of interdependent parts, like the human body.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 49, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Transmitting ideas through spoken or written words is called:', '["Non-verbal communication", "Verbal communication", "Diagonal communication", "Effective communication"]'::jsonb, 1, 'Verbal communication uses spoken or written words.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 50, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which one of the following is a step of controlling?', '["Assessing personnel required", "Taking disciplinary action", "Taking corrective action", "Assessing environment"]'::jsonb, 2, 'Controlling: set standards, measure performance, compare and analyse deviations, take corrective action.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 51, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'The four elements that must be proven to establish nursing negligence are:', '["Duty, breach of duty, causation, and damages", "Autonomy, beneficence, non-maleficence, and justice", "Consent, capacity, competence, and cost", "Assessment, diagnosis, planning, and evaluation"]'::jsonb, 0, 'Legal negligence requires demonstrating a duty of care existed, that duty was breached, the breach caused harm, and measurable damages resulted.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 52, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which of the following characterize a manager as being effective?', '["They achieve their goals.", "They devote a large amount of time to planning.", "They interview, select, and train people who are most suitable to fill open jobs.", "They use a minimum amount of resources for the amount of outputs produced."]'::jsonb, 0, 'Effectiveness means achieving the goals.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 53, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Management is a ___ directed process as it aims at achieving specified goals.', '["Continuously", "Deliberately", "Future", "Goal"]'::jsonb, 3, 'Management is goal-directed: every activity aims at specified goals.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 54, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Influencing and inspiring subordinates to achieve results is:', '["Control", "Administration", "Leadership", "Management"]'::jsonb, 2, 'Leadership is influencing and inspiring others to achieve results.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 55, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'A patient''s confidential information may be disclosed in which instance?', '["In order to take him to the hospital", "To tell the doctor the truth", "To prevent harm or grievous injury", "To pay the patient''s hospital bill"]'::jsonb, 2, 'Confidential information may be disclosed without consent when needed to prevent serious harm to the patient or others, or when required by law.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 56, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'The nurse responsible for coordinating the activities of a nursing team is the:', '["Ward orderly", "Pharmacist", "Medical officer", "Team leader"]'::jsonb, 3, 'The team leader coordinates and directs the activities of the nursing team members.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 57, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Objective of the principle of ''order'' in healthcare management?', '["Receiving orders from bottom to top", "Framework for receiving top management orders", "Orderly arrangement for resources", "Framework for giving orders"]'::jsonb, 2, 'Fayol''s principle of order means "a place for everything and everything in its place", the orderly arrangement of people and materials.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 58, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Identify the feature of co-ordination being highlighted in the given statement: “Coordination is not a one time function, it begins at the planning stage and continue till controlling.”', '["Coordination is a continuous process", "Coordination ensures unity of action", "Coordination is an all pervasive function", "Coordination is a deliberate function"]'::jsonb, 0, 'Coordination is continuous: it starts at planning and runs through to controlling.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 59, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which one of the following is a semantic barrier?', '["Organisational policy", "Status", "Lack of attention", "Technical jargon"]'::jsonb, 3, 'Semantic barriers come from language, e.g. technical jargon or faulty translation.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 60, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Pervasiveness of planning indicates that planning', '["is a future-oriented activity.", "is a top management function.", "extends throughout the organisation.", "is the first element of management process."]'::jsonb, 2, 'Planning is pervasive: it happens at every level and in every department.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 61, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'The goal of quality assurance in nursing is to:', '["Meet the minimum legal standards of care", "Ensure nurses follow all orders without question", "Reduce the cost of care", "Continuously improve patient care and outcomes"]'::jsonb, 3, 'The ultimate goal of quality assurance is to provide the best possible care for patients. This involves a continuous cycle of evaluating care, identifying opportunities for improvement, and implementing changes to enhance patient safety and outcomes.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 62, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', '__________ involves harmony and team spirit among employees.', '["Standardisation", "Order", "Esprit de corps", "Discipline"]'::jsonb, 2, 'Esprit de corps promotes team spirit and harmony.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 63, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'The main task of this level of management is to determine the overall organisational objectives and strategies for their realisation.', '["First line managers", "Operational management", "Middle level management", "Top level management"]'::jsonb, 3, 'Top-level management sets overall objectives and strategies.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 64, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which quality improvement model is widely used in healthcare?', '["PDSA Cycle", "SWOT", "Fishbone Diagram", "Gantt Chart"]'::jsonb, 0, 'The Plan-Do-Study-Act (PDSA) cycle is a widely used quality improvement model in healthcare.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 65, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Who is called the father of scientific management?', '["Jean Piaget", "Frederick Taylor", "Ivan Pavlov", "Thomas Jefferson"]'::jsonb, 1, 'Frederick W. Taylor is called the father of scientific management. Fayol is the father of modern (administrative) management.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 66, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which one of the following sources is most relevant to recruiting managerial personnel?', '["Direct recruitment", "Employment exchange", "Advertisement", "Casual callers"]'::jsonb, 2, 'Managerial vacancies are usually filled through advertisement, which reaches suitably qualified candidates.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 67, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which one of the following is an internal source of recruitment?', '["Transfer", "Employee recommendations", "Campus recruitment", "Personal contacts"]'::jsonb, 0, 'Transfer and promotion are internal sources of recruitment.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 68, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Controlling in management is of which type?', '["Corrective only", "Preventive only", "Both preventive and corrective", "Neither preventive nor corrective"]'::jsonb, 2, 'Controlling is both preventive (anticipating problems) and corrective (fixing deviations).', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 69, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'A patient is transitioning to hospice care. The nurse explains this focuses on:', '["Palliation and comfort", "Aggressive resuscitation", "Curative treatment", "Life-prolonging therapies"]'::jsonb, 0, 'Hospice prioritizes comfort, symptom management, and quality of life.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 70, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Negligence requires proof of:', '["A complaint alone from the family", "An error alone, even with no harm", "Harm alone, whatever the cause", "Duty, breach, causation and harm"]'::jsonb, 3, 'Retained swabs are classic examples of negligence.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 71, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'The lowest measurement scale in statistics is the:', '["Ratio scale", "Nominal scale", "Interval scale", "Ordinal scale"]'::jsonb, 1, 'The levels of measurement, lowest to highest, are nominal, ordinal, interval and ratio.', 'NNP 418 · Research Methods and Statistics'),
(3, 72, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Before a data collection tool (such as a questionnaire) is used in the main study, it should first undergo:', '["Immediate distribution to all participants without review", "Translation into as many languages as possible regardless of relevance", "Pilot testing to check its clarity, validity, and reliability", "Full statistical analysis of anticipated results"]'::jsonb, 2, 'Pilot testing on a small group prior to the main study helps identify problems with clarity, validity, and reliability of the instrument before full-scale use.', 'NNP 418 · Research Methods and Statistics'),
(3, 73, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Research control means holding constant other influences that might affect the:', '["Conditioned variable", "Dependent variable", "Independent variable", "Antecedent variable"]'::jsonb, 1, 'Research control holds extraneous influences constant so that changes in the dependent variable can be put down to the independent variable.', 'NNP 418 · Research Methods and Statistics'),
(3, 74, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'The original source from which researcher collects information is', '["Secondary Source", "Primary Source", "Both primary and secondary", "Tertiary source"]'::jsonb, 1, 'The original, first-hand source of information is a primary source.', 'NNP 418 · Research Methods and Statistics'),
(3, 75, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which of the following pain scale is best to be used for assessment of pain of in adults with pain?', '["Simple description pain intensity scale", "McGill-Melzack pain questionnaire", "Faces pain-rating scale", "0-10 numeric pain scale"]'::jsonb, 3, 'The 0-10 numeric scale is the most widely used, quick, and validated tool for adults who can self-report.', 'NNP 418 · Research Methods and Statistics'),
(3, 76, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A patient receiving a lipid-containing TPN infusion should have which laboratory value monitored to detect a potential metabolic complication of the lipid emulsion?', '["Serum amylase level only", "Serum uric acid level", "Serum triglyceride level", "Serum bilirubin level only"]'::jsonb, 2, 'Lipid emulsions can cause hypertriglyceridemia, particularly if infused too rapidly, so serum triglyceride levels should be monitored periodically during lipid administration.', 'NNP 418 · Research Methods and Statistics'),
(3, 77, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Sterilisation by steam (autoclave) at 134 °C usually takes:', '["3 minutes holding time", "24 hours holding time", "1 hour holding time", "30 seconds holding time"]'::jsonb, 0, '121 °C requires 15 minutes holding time.', 'NNP 418 · Research Methods and Statistics'),
(3, 78, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'In a normal distribution, the mean, median, and mode are:', '["Dependent on sample size", "Equal to each other", "Always zero", "All different values"]'::jsonb, 1, 'In a perfectly normal (bell-shaped) distribution, the mean, median, and mode coincide at the center of the curve.', 'NNP 418 · Research Methods and Statistics'),
(3, 79, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'In experimental research, which group is the basis for determining the effect of the intervention?', '["Experimental group", "Control group", "Sample group", "Whole population"]'::jsonb, 1, 'The control group gives the baseline for judging the effect of the intervention.', 'NNP 418 · Research Methods and Statistics'),
(3, 80, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which of the following data collection methods relies most heavily on the nurse''s use of the senses (sight, hearing, smell, touch) without direct questioning of the client?', '["Chart review", "Interview", "Consultation with the physician", "Observation"]'::jsonb, 3, 'Observation relies on the nurse''s senses to gather data about the client''s appearance, behavior, and environment without direct questioning.', 'NNP 418 · Research Methods and Statistics'),
(3, 81, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which of the following is a non-probability sampling method?', '["Stratified", "Simple random", "Snowball", "Cluster"]'::jsonb, 2, 'Snowball sampling (participants recruit others) is non-probability. Random, cluster and stratified sampling are probability methods.', 'NNP 418 · Research Methods and Statistics'),
(3, 82, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'The hypothesis that states there is no difference between groups is the:', '["Null hypothesis", "Research question", "Conceptual framework", "Alternative hypothesis"]'::jsonb, 0, 'Statistical tests assess evidence against the null hypothesis. A p-value below 0.05 is commonly taken as significant.', 'NNP 418 · Research Methods and Statistics'),
(3, 83, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A survey is mainly a ______ study.', '["Experimental", "Laboratory", "Historical", "Descriptive"]'::jsonb, 3, 'A survey is a descriptive study.', 'NNP 418 · Research Methods and Statistics'),
(3, 84, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'In research, the term "universe" refers to the:', '["Research instrument", "Sample", "Entire population", "Study setting"]'::jsonb, 2, 'The "universe" is the whole population: all the units of interest.', 'NNP 418 · Research Methods and Statistics'),
(3, 85, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'The concrete observable events which represent the abstract concepts or constructs are called', '["Proposition", "Sample", "Data", "Variable"]'::jsonb, 3, 'Concrete, observable representations of abstract concepts are variables.', 'NNP 418 · Research Methods and Statistics'),
(3, 86, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Reliability of a research instrument refers to its:', '["Consistency in producing the same results", "Cost", "Ability to measure what it is meant to measure", "Length"]'::jsonb, 0, 'Validity is whether it measures what it intends to measure. A tool can be reliable without being valid.', 'NNP 418 · Research Methods and Statistics'),
(3, 87, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A sickle cell disease patient''s haemoglobin genotype is:', '["HbAC", "HbSS", "HbAA", "HbAS"]'::jsonb, 1, 'HbAS is the carrier (trait).', 'NNP 418 · Research Methods and Statistics'),
(3, 88, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which data collection method involves direct questioning of participants through a structured set of questions?', '["Questionnaire/Interview", "Document review", "Observation", "Physiological measurement"]'::jsonb, 0, 'Questionnaires and interviews are primary data collection methods using structured or semi-structured questions.', 'NNP 418 · Research Methods and Statistics'),
(3, 89, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'All the followings are method of data collection except', '["Observation", "Experiment", "Interview (focus group)", "Frequency chart"]'::jsonb, 3, 'The correct answer is: Frequency chart.', 'NNP 418 · Research Methods and Statistics'),
(3, 90, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which of the following phrases would be found in a report of a qualitative study?', '["\"Perceived pain was measured using the nominal pain scale?\"", "\"The control group received no instruction?\"", "\"Subjects were asked to relate their perceptions of pain?\"", "\"The hypothesis of this study is?\""]'::jsonb, 2, 'Qualitative studies explore participants'' own perceptions and experiences, e.g. asking them to describe their pain.', 'NNP 418 · Research Methods and Statistics'),
(3, 91, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which is NOT a probability sampling method?', '["Stratified random sampling", "Simple random sampling", "Cluster sampling", "Convenience sampling"]'::jsonb, 3, 'Convenience sampling is non-probability. Simple random, cluster and stratified sampling give every unit a known chance of selection.', 'NNP 418 · Research Methods and Statistics'),
(3, 92, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A researcher studying the culture and way of life of nurses in a Nigerian tertiary hospital is using which qualitative approach?', '["Phenomenology", "Grounded theory", "Ethnography", "Historical research"]'::jsonb, 2, 'Ethnography studies cultural patterns, behaviors, and shared meanings within a group or community in their natural setting.', 'NNP 418 · Research Methods and Statistics'),
(3, 93, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'The variable that is measured for an effect after the independent variable is manipulated is the:', '["Control variable", "Independent variable", "Intervening variable", "Dependent variable"]'::jsonb, 3, 'The dependent variable is the outcome variable measured to determine the effect of the independent variable.', 'NNP 418 · Research Methods and Statistics'),
(3, 94, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A patient''s choices, preferences and decisions are assessed under:', '["Cognition and perception", "Nutrition and metabolism", "Self-perception and self-concept", "Values and beliefs"]'::jsonb, 3, 'The values–beliefs pattern covers the patient''s values, goals, choices and spiritual beliefs that guide decisions.', 'NNP 418 · Research Methods and Statistics'),
(3, 95, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A patient''s vital sign trends are monitored continuously, and the information is used to adjust nursing interventions in real time. This best illustrates which systems theory concept?', '["Entropy", "Suprasystem", "Equifinality", "Feedback"]'::jsonb, 3, 'Feedback is the mechanism by which information about a system''s output is returned to the system to regulate and adjust its functioning, similar to how ongoing patient data guides nursing care.', 'NNP 418 · Research Methods and Statistics'),
(3, 96, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'At the ratio level of measurement, the most appropriate index of central tendency is usually the:', '["Mean", "Range", "Median", "Mode"]'::jsonb, 0, 'For interval or ratio data that are roughly symmetrical, the mean is the most appropriate measure of central tendency.', 'NNP 418 · Research Methods and Statistics'),
(3, 97, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Your patient has developed a low-grade fever and states that she has felt very tired lately. You interpret these findings as indicating which stage of infection?', '["Full stage of illness", "Convalescent period", "Incubation period", "Prodromal stage"]'::jsonb, 3, 'Low-grade fever and fatigue before specific symptoms appear describe the prodromal stage of infection.', 'NNP 418 · Research Methods and Statistics'),
(3, 98, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which of the following is an example of a common ERROR in writing a nursing diagnosis, in which the statement is written as a medical diagnosis rather than a nursing diagnosis?', '["\"Activity Intolerance related to fatigue\"", "\"Acute Pain related to tissue trauma\"", "\"Diagnosis: Congestive Heart Failure\"", "\"Deficient Fluid Volume related to vomiting\""]'::jsonb, 2, '"Congestive Heart Failure" is a medical diagnosis naming a disease process, not a nursing diagnosis describing the client''s response, and should not be used as one.', 'NNP 418 · Research Methods and Statistics'),
(3, 99, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Quality assurance in ICU uses Donabedian''s framework of:', '["Structure, process and outcome", "Assessment, diagnosis and planning", "Input, output and feedback only", "Planning, organising and controlling"]'::jsonb, 0, 'Structure: resources; process: activities; outcome: results.', 'NNP 418 · Research Methods and Statistics'),
(3, 100, 'Nephrology Nursing Mock — Day 3 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A frequency polygon is drawn by:', '["Placing columns whose width is the class interval", "Inserting a table in the corner of the graph", "Joining the plotted points with straight lines", "Placing bars on class midpoints"]'::jsonb, 2, 'A frequency polygon plots class midpoints against frequency and joins the points with straight lines.', 'NNP 418 · Research Methods and Statistics');
